#!/usr/bin/env python3
import json,sys,os
RUN=os.path.dirname(os.path.abspath(__file__))
t,k,epic=sys.argv[1],sys.argv[2],sys.argv[3]
l=next(x for x in json.load(open(f'{RUN}/plan/{t}.json')) if x['key']==k)
b=['## Contexte',f"Lot `{k}` de la piste **{t}** du programme de parité Android ↔ iOS (directive #11570, épopée #{epic}). Domaine `{l['domain']}`, priorité {l['priority']}, effort {l['effort']}.",'',l.get('goal',''),'',
f"Relevé du domaine : `apps/android/docs/parite-ios/{l['domain']}.md`. Conventions : `apps/android/docs/parite-ios/CONVENTIONS.md`.",'']
if l.get('ios_reference_files'): b+=['Références iOS :']+[f'- `{x}`' for x in l['ios_reference_files']]+['']
if l.get('absorbed'): b+=['Lots absorbés (leurs critères sont repris ci-dessous) : '+', '.join(f'`{x}`' for x in l['absorbed']),'']
if l.get('deps'): b+=['Dépend de (fusionnés dans dev avant le démarrage) : '+', '.join(f'`{x}`' for x in l['deps']),'']
b+=['## Preuve attendue (critères d\'acceptation)']+[f'- [ ] {x}' for x in l.get('acceptance',[])]+['','## Tests à écrire d\'abord']+[f'- {x}' for x in l.get('tests',[])]+['',
'## Critère de fin',"La PR de la branche `claude/android-"+k+"` est fusionnée dans `dev` avec `android.yml` vert (assembleDebug + testDebugUnitTest). Le comportement, les états, les gestes et le rendu sont ceux des références iOS. Ce qui n'est pas mûr devient une issue.",'','---','_Generated by [Claude Code](https://claude.ai/code)_']
print(json.dumps({'title':l['title'],'body':'\n'.join(b)},ensure_ascii=False))
